+      color: #03111f;
+      cursor: pointer;
+      font: inherit;
+      font-weight: 800;
+      letter-spacing: 0.01em;
+      transition: transform 160ms ease, filter 160ms ease, box-shadow 160ms ease;
+    }
+
+    button:hover {
+      filter: brightness(1.08);
+      box-shadow: 0 0.75rem 1.5rem rgba(56, 189, 248, 0.18);
+    }
+
+    button:focus-visible {
+      outline: 0.2rem solid var(--focus);
+      outline-offset: 0.2rem;
+    }
+
+    button:active {
+      transform: translateY(1px);
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <section class="contact-card" aria-labelledby="support-heading">
+      <h1 id="support-heading">Contact support</h1>
+      <p class="intro">Tell us how to reach you and our support team will follow up.</p>
+
+      <form id="support-form" novalidate>
+        <div class="form-field">
+          <label for="full-name">Full name <span aria-hidden="true">*</span></label>
+          <input
+            type="text"
+            id="full-name"
+            name="fullName"
+            autocomplete="name"
+            required
+            aria-describedby="full-name-error"
+          >
+          <p class="error-message" id="full-name-error" aria-live="polite"></p>
+        </div>
+
+        <div class="form-field">
+          <label for="email">Email address <span aria-hidden="true">*</span></label>
+          <input
+            type="email"
+            id="email"
+            name="email"
+            autocomplete="email"
+            required
+            aria-describedby="email-error"
+          >
+          <p class="error-message" id="email-error" aria-live="polite"></p>
+        </div>
+
+        <div class="form-field">
+          <label for="phone">Phone number</label>
+          <input
+            type="tel"
+            id="phone"
+            name="phone"
+            autocomplete="tel"
+            placeholder="555-123-4567"
+            aria-describedby="phone-helper phone-error"
+          >
+          <p class="helper-text" id="phone-helper">Optional. Use 10 digits, such as 555-123-4567.</p>
+          <p class="error-message" id="phone-error" aria-live="polite"></p>
+        </div>
+
+        <button type="submit">Submit request</button>
+        <p class="status-message" id="form-status" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.querySelector("#support-form");
+    const fields = {
+      fullName: {
+        input: document.querySelector("#full-name"),
+        error: document.querySelector("#full-name-error"),
+        validate(value) {
+          return value.trim() ? "" : "Enter your full name.";
+        }
+      },
+      email: {
+        input: document.querySelector("#email"),
+        error: document.querySelector("#email-error"),
+        validate(value) {
+          const trimmedValue = value.trim();
+          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+          if (!trimmedValue) {
+            return "Enter your email address.";
+          }
+
+          return emailPattern.test(trimmedValue) ? "" : "Enter a valid email address.";
+        }
+      },
+      phone: {
+        input: document.querySelector("#phone"),
+        error: document.querySelector("#phone-error"),
+        validate(value) {
+          const trimmedValue = value.trim();
+          const phonePattern = /^(\+1\s?)?(\(?\d{3}\)?[\s.-]?)\d{3}[\s.-]?\d{4}$/;
+
+          if (!trimmedValue) {
+            return "";
+          }
+
+          return phonePattern.test(trimmedValue) ? "" : "Enter a valid phone number, such as 555-123-4567.";
+        }
+      }
+    };
+    const statusMessage = document.querySelector("#form-status");
+
+    function setError(field, message) {
+      field.error.textContent = message;
+      field.input.setAttribute("aria-invalid", message ? "true" : "false");
+    }
+
+    function validateField(field) {
+      const message = field.validate(field.input.value);
+      setError(field, message);
+      return !message;
+    }
+
+    Object.values(fields).forEach((field) => {
+      field.input.addEventListener("input", () => {
+        validateField(field);
+        statusMessage.textContent = "";
+      });
+    });
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+
+      const isValid = Object.values(fields).every(validateField);
+      statusMessage.textContent = "";
+
+      if (!isValid) {
+        const firstInvalidInput = form.querySelector('[aria-invalid="true"]');
+        firstInvalidInput.focus();
+        return;
+      }
+
+      form.reset();
+      Object.values(fields).forEach((field) => setError(field, ""));
+      statusMessage.textContent = "Thanks. Your support request is ready to send.";
+    });
+  </script>
+</body>
+</html>
*** End Patch
