<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #080c14;
      --panel: #111827;
      --panel-strong: #182235;
      --text: #f8fafc;
      --muted: #b8c1d1;
      --border: #334155;
      --focus: #7dd3fc;
      --accent: #38bdf8;
      --accent-strong: #0284c7;
      --error: #fca5a5;
      --error-border: #ef4444;
      --success: #86efac;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 2rem;
      background:
        radial-gradient(circle at top left, rgba(56, 189, 248, 0.22), transparent 32rem),
        linear-gradient(135deg, #050816 0%, var(--bg) 52%, #0f172a 100%);
      color: var(--text);
      font-family: Arial, Helvetica, sans-serif;
      line-height: 1.5;
    }

    main {
      width: min(100%, 36rem);
    }

    .contact-card {
      padding: clamp(1.5rem, 4vw, 2.5rem);
      border: 1px solid rgba(148, 163, 184, 0.22);
      border-radius: 1.25rem;
      background: rgba(17, 24, 39, 0.9);
      box-shadow: 0 1.5rem 4rem rgba(0, 0, 0, 0.45);
      backdrop-filter: blur(18px);
    }

    h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(2rem, 6vw, 3rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 2rem;
      color: var(--muted);
    }

    .form-field {
      margin-bottom: 1.25rem;
    }

    label {
      display: block;
      margin-bottom: 0.45rem;
      color: var(--text);
      font-weight: 700;
    }

    input {
      width: 100%;
      min-height: 3rem;
      padding: 0.85rem 1rem;
      border: 1px solid var(--border);
      border-radius: 0.75rem;
      background: var(--panel-strong);
      color: var(--text);
      font: inherit;
      transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
    }

    input::placeholder {
      color: #8490a3;
    }

    input:focus {
      outline: none;
      border-color: var(--focus);
      box-shadow: 0 0 0 0.2rem rgba(125, 211, 252, 0.22);
      background: #1f2937;
    }

    input[aria-invalid="true"] {
      border-color: var(--error-border);
    }

    .helper-text,
    .error-message,
    .status-message {
      margin: 0.45rem 0 0;
      font-size: 0.95rem;
    }

    .helper-text {
      color: var(--muted);
    }

    .error-message {
      min-height: 1.45rem;
      color: var(--error);
      font-weight: 700;
    }

    .status-message {
      color: var(--success);
      font-weight: 700;
    }

    button {
      width: 100%;
      min-height: 3.2rem;
      margin-top: 0.25rem;
      border: 0;
      border-radius: 0.85rem;
      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
      color: #03111f;
      cursor: pointer;
      font: inherit;
      font-weight: 800;
      letter-spacing: 0.01em;
      transition: transform 160ms ease, filter 160ms ease, box-shadow 160ms ease;
    }

    button:hover {
      filter: brightness(1.08);
      box-shadow: 0 0.75rem 1.5rem rgba(56, 189, 248, 0.18);
    }

    button:focus-visible {
      outline: 0.2rem solid var(--focus);
      outline-offset: 0.2rem;
    }

    button:active {
      transform: translateY(1px);
    }
  </style>
</head>
<body>
  <main>
    <section class="contact-card" aria-labelledby="support-heading">
      <h1 id="support-heading">Contact support</h1>
      <p class="intro">Tell us how to reach you and our support team will follow up.</p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">Full name <span aria-hidden="true">*</span></label>
          <input
            type="text"
            id="full-name"
            name="fullName"
            autocomplete="name"
            required
            aria-describedby="full-name-error"
          >
          <p class="error-message" id="full-name-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="email">Email address <span aria-hidden="true">*</span></label>
          <input
            type="email"
            id="email"
            name="email"
            autocomplete="email"
            required
            aria-describedby="email-error"
          >
          <p class="error-message" id="email-error" aria-live="polite"></p>
        </div>

        <div class="form-field">
          <label for="phone">Phone number</label>
          <input
            type="tel"
            id="phone"
            name="phone"
            autocomplete="tel"
            placeholder="555-123-4567"
            aria-describedby="phone-helper phone-error"
          >
          <p class="helper-text" id="phone-helper">Optional. Use 10 digits, such as 555-123-4567.</p>
          <p class="error-message" id="phone-error" aria-live="polite"></p>
        </div>

        <button type="submit">Submit request</button>
        <p class="status-message" id="form-status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#support-form");
    const fields = {
      fullName: {
        input: document.querySelector("#full-name"),
        error: document.querySelector("#full-name-error"),
        validate(value) {
          return value.trim() ? "" : "Enter your full name.";
        }
      },
      email: {
        input: document.querySelector("#email"),
        error: document.querySelector("#email-error"),
        validate(value) {
          const trimmedValue = value.trim();
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

          if (!trimmedValue) {
            return "Enter your email address.";
          }

          return emailPattern.test(trimmedValue) ? "" : "Enter a valid email address.";
        }
      },
      phone: {
        input: document.querySelector("#phone"),
        error: document.querySelector("#phone-error"),
        validate(value) {
          const trimmedValue = value.trim();
          const phonePattern = /^(\+1\s?)?(\(?\d{3}\)?[\s.-]?)\d{3}[\s.-]?\d{4}$/;

          if (!trimmedValue) {
            return "";
          }

          return phonePattern.test(trimmedValue) ? "" : "Enter a valid phone number, such as 555-123-4567.";
        }
      }
    };
    const statusMessage = document.querySelector("#form-status");

    function setError(field, message) {
      field.error.textContent = message;
      field.input.setAttribute("aria-invalid", message ? "true" : "false");
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      setError(field, message);
      return !message;
    }

    Object.values(fields).forEach((field) => {
      field.input.addEventListener("input", () => {
        validateField(field);
        statusMessage.textContent = "";
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const isValid = Object.values(fields).every(validateField);
      statusMessage.textContent = "";

      if (!isValid) {
        const firstInvalidInput = form.querySelector('[aria-invalid="true"]');
        firstInvalidInput.focus();
        return;
      }

      form.reset();
      Object.values(fields).forEach((field) => setError(field, ""));
      statusMessage.textContent = "Thanks. Your support request is ready to send.";
    });
  </script>
</body>
</html>
